<template>
  <div class="invite" :class="theme.id" :style="vars">
    <section v-if="!opened" class="cover" :style="coverStyle"><div><p>{{ theme.kicker }}</p><b>{{ monogram }}</b><h1>{{ groomName }} <i>&amp;</i> {{ brideName }}</h1><time>{{ dateLabel }}</time><button @click="open">MỞ THIỆP</button></div></section>
    <main v-else>
