<script setup>
import { computed, nextTick, ref } from 'vue'; import dayjs from 'dayjs'; import FloatingMusic from '@/components/common/FloatingMusic.vue';
const props=defineProps({wedding:{type:Object,required:true},theme:{type:Object,required:true}}); const opened=ref(false),musicRef=ref(null); const get=(o,...keys)=>keys.map(k=>o?.[k]).find(v=>v!==undefined&&v!==null&&v!==''); const groom=computed(()=>props.wedding?.couple?.Groom||props.wedding?.couple?.groom||{}),bride=computed(()=>props.wedding?.couple?.Bride||props.wedding?.couple?.bride||{}); const groomName=computed(()=>get(props.wedding,'GroomName','groomName')||get(groom.value,'Name','name')||'Chú rể'),brideName=computed(()=>get(props.wedding,'BrideName','brideName')||get(bride.value,'Name','name')||'Cô dâu'); const monogram=computed(()=>`${groomName.value[0]}&${brideName.value[0]}`.toUpperCase()); const rawDate=computed(()=>get(props.wedding?.hero,'WeddingDate','weddingDate')||get(props.wedding,'WeddingDate','weddingDate')); const dateLabel=computed(()=>{const d=dayjs(rawDate.value);return d.isValid()?d.format('DD · MM · YYYY'):''}); const image=computed(()=>get(props.wedding,'coverImage','CoverImage')||get(props.wedding?.hero,'Image','image','Background','background')||''); const coverStyle=computed(()=>image.value?{'--cover':`url("${image.value}")`}:{}); const vars=computed(()=>({'--primary':props.theme.primary,'--accent':props.theme.accent,'--paper':props.theme.paper,'--ink':props.theme.ink,'--muted':props.theme.muted})); const events=computed(()=>Array.isArray(props.wedding?.events)?props.wedding.events:[]),timeline=computed(()=>Array.isArray(props.wedding?.timeline)?props.wedding.timeline:[]),gallery=computed(()=>Array.isArray(props.wedding?.gallery)?props.wedding.gallery:[]),gifts=computed(()=>Array.isArray(props.wedding?.gifts)?props.wedding.gifts:[]); const story=computed(()=>get(props.wedding?.story,'Description','description','Content','content')||''); const wishes=computed(()=>{const b=props.wedding?.guestBook||props.wedding?.GuestBook;return Array.isArray(b)?b:b?.Guest||b?.guest||b?.wishes||[]}); const people=computed(()=>[{role:'Chú rể',name:groomName.value,image:get(groom.value,'Avatar','avatar','Image','image'),description:get(groom.value,'Description','description')},{role:'Cô dâu',name:brideName.value,image:get(bride.value,'Avatar','avatar','Image','image'),description:get(bride.value,'Description','description')}]); const music=computed(()=>{const m=props.wedding?.music||{};return {Enabled:m.Enabled??m.enabled??false,Url:m.Url||m.url||'',Title:m.Title||m.title||''}}); function on(name){const s=props.wedding?.settings||props.wedding?.Settings||{};return (s[`Show${name}`]??s[`show${name}`])!==false} async function open(){opened.value=true;await nextTick();musicRef.value?.play?.()}
